question.answer:
package main

import "strconv"

func total(readings []string) (int, error) {
	sum := 0
	for _, r := range readings {
		n, err := strconv.Atoi(r)
		if err != nil {
			return 0, err
		}
		sum += n
	}
	return sum, nil
}

