question.answer:
package main

import (
	"errors"
	"fmt"
)

type Parcel struct {
	Weight int
	Dest   string
}

func label(p Parcel) (string, error) {
	if p.Weight < 1 {
		return "", errors.New("empty parcel")
	}
	if p.Weight > 20000 {
		return "", errors.New("too heavy")
	}
	if p.Dest == "" {
		return "", errors.New("no destination")
	}
	return fmt.Sprintf("%s %dg", p.Dest, p.Weight), nil
}

testcode.text:
for _, p := range []Parcel{{1, "Skye"}, {20000, "Ely"}, {20001, "Ely"}} {
	s, err := label(p)
	if err != nil {
		fmt.Println(err)
		continue
	}
	fmt.Println(s)
}

