question.answer:
package main

import "errors"

var (
	ErrNotInvited  = errors.New("not on the list")
	ErrAfterCurfew = errors.New("after curfew")
	ErrHallFull    = errors.New("hall full")
)

type Gate struct {
	invited  map[string]bool
	curfew   int
	capacity int
	inside   int
}

func NewGate(invited []string, curfew, capacity int) *Gate {
	g := &Gate{invited: map[string]bool{}, curfew: curfew, capacity: capacity}
	for _, name := range invited {
		g.invited[name] = true
	}
	return g
}

func (g *Gate) Admit(name string, hour int) error {
	if !g.invited[name] {
		return ErrNotInvited
	}
	if hour >= g.curfew {
		return ErrAfterCurfew
	}
	if g.inside >= g.capacity {
		return ErrHallFull
	}
	g.inside++
	return nil
}

func verdict(err error) string {
	switch {
	case errors.Is(err, ErrNotInvited):
		return "turned away, fetch the steward"
	case errors.Is(err, ErrAfterCurfew):
		return "turned away, come back at dawn"
	case errors.Is(err, ErrHallFull):
		return "turned away, wait by the fire"
	case err != nil:
		return "turned away"
	}
	return "admitted"
}
